      <span class="total-val">
        ${a?`${Math.round(e.amount).toLocaleString()} ج.م`:h?`${Math.round(f).toLocaleString()} ج.م`:p?"0 ج.م (خالص)":`+${Math.round(Math.abs(f)).toLocaleString()} ج.م (دائن)`}
      </span>
